			autoTableHeight() {
				console.log(this.$route.query.lx)
				this.tableHeight = window.innerHeight - 235;
				window.onresize = () => {
					return (() => {
						this.tableHeight = window.innerHeight - 235;
					})();
				};
			},
             getkhData() {
               Query({
							tj:true,
							tablename:'客户',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							//console.log(res.data)
							this.khList = res.data							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 }, 
			  getcpData() {
               Query({
							tj:true,
							tablename:'产品',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							//console.log(res.data)
							this.cpList = res.data							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 },  
			getAuthKeys() {
            let sj =   JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			 let info = this.$store.state.d2admin.user.info
			 if(info.name == 'admin'){
				this.authKeys = true
				console.log(this.authKeys)	
				  setTimeout(() =>{
                 this.getTableData()
				 },200)
				
							/* let qx;
                      	Query({
							tablename:'菜单',
							columns:'二级菜单',
							field:'id',
							tj:true,
						})
						.then(resl => {
							 qx  = resl.map(function (v,){
								return v.二级菜单
							})
							console.log(qx);
						this.authKeys = qx
						this.getTableData()
						this.uname = info.name
						}).catch(err => {}) */
						}else{
				GetMenuTreeOnAuth({
                  username:info.name
				})
					.then(res => {			
                          let js = res.data.角色	
				         this.authKeys = ['超级管理员','开票员'].includes(js)
				         console.log(this.authKeys)	
						this.getTableData()
						this.uname = info.name

					})
					.catch(err => {})
						}
			},
			getTableData() {
					let tjx	
					let tjy	
					let tjz
					let tj = `类型 = '销售出库'`
					//let ss 
				//if (this.authKeys.indexOf('消息通知') > -1) {
					this.loading = true
                if(this.$route.query.lx == 'xs'){
                       console.log('(isnull(状态) or 状态=0 )')
				}else if(this.$route.query.lx != 'xs'){
                      console.log(true)
				}
				 if(this.searchFilter.name !='' && this.searchFilter.name != null ){
					tjx =`客户ID= '${this.searchFilter.name}'`	
					tj = tj + ' and ' +tjx
					}else{
						tjx = true
						tj = tj + ' and ' + tjx 
					}
				if(this.searchFilter.disable == '否'){
                       tjy = '(isnull(状态) or 状态=0 )'
					   tj += ' and ' + tjy
					}else if(this.searchFilter.disable == '是'){
						tjy = '状态=-1' 
						tj += ' and ' + tjy
					}
					 if(this.searchFilter.riqi){
						console.log(this.searchFilter.riqi)
					tjz =`日期 in ('${this.searchFilter.riqi}')`	
					tj += ' and ' + tjz
					}
					Query({
							//pageSize: this.tablePage.pageSize,//每页条数 相当于layui的limit
							//currentPage: this.tablePage.currentPage, // 相当于layui的page
							//searchFilter: this.searchFilter  
							limit: this.tablePage.pageSize,
							page: this.tablePage.currentPage,
							tj:tj,
							tablename:'销售',
							field:'id',
							order:'desc',
						})
						.then(res => {							
						let khsj = this.khList
					    let ss = res.data.map(function(v,i) {
						let obj4 = khsj.find(o => o.客户ID === v.客户ID); 
						console.log(obj4.客户名称)
						  //this.dwMc = obj4.客户名称
						delete obj4.id;
						delete obj4.日期;
						 return   Object.assign(v,obj4);						
						});	
						console.log(ss)
						this.tableData = ss
						this.tablePage.totalResult = res.count
						this.loading = false
							
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				//}
			   
			},
			  toggleExpandMethod ({ expanded, row }) {
				  if (expanded) {
				 console.log(row.单据编号)
				 let tj = '单据编号' + "=" +  '"' + row.单据编号 + '"';
				 Query({
							tj:tj,
							tablename:'出单',
							field:'id'
						})
						.then(res => {
						let cpsj = this.cpList
					    let ssy = res.data.map(function(v,i) {
						let obj5 = cpsj.find(o => o.产品ID === v.产品ID); 
						delete obj5.id;
						delete obj5.日期;
						 return   Object.assign(v,obj5);						
						});	
						console.log(ssy)
							this.childData = ssy							 							
						})
						.catch(err => {
							// 异常情况
							
						})
				  }
              return true
            }, 
	
			shenhe(){

			},
			fanshen(){

			},
			handleSearch() {
				this.tablePage.currentPage = 1 //注意要回来第一页
				this.getTableData()
			},
			handlePageChange({
				currentPage,
				pageSize
			}) {
				this.tablePage.currentPage = currentPage
				this.tablePage.pageSize = pageSize
				this.getTableData()
			},
			clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					this.searchFilter
					obj[key] = null
				}
			},

			exportDataEvent() {
				this.$refs.xTable1.exportData({
					type: 'csv'
				})
			},

			//用户采购
			deleteCginfo() {
				let _this = this
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				let tempIDs = []
				let tempBHs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.id)
					console.log(tempIDs)
					tempBHs.push(sr.单据编号)
					console.log(tempBHs)
				}
				
	
				if (tempIDs.length > 0) {
					this.$confirm('确定要永久删除这' + tempIDs.length + '行?', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						type: 'warning'
					}).then(() => {
						this.fullscreenLoading = true
						Aud({
								//id: tempIDs.join(',')
						reqType:'delete',
						content:tempIDs,
						tablename:'销售'
							})
							.then(res => {
								this.fullscreenLoading = false
								_this.deleteMx(tempBHs)
								this.getTableData()
								this.$message.success('删除成功')
							})
							.catch(err => {
								this.fullscreenLoading = false
							})
					}).catch(() => {});
				} else {
					this.$message.warning('请先勾选要删除的行')
				} 
			},

             deleteMx(deid){
				 console.log(deid)
				 deid.forEach(function(v){
				 let tj = '单据编号' + "=" +  '"' + v + '"';
				 Query({
							tj:tj,
							tablename:'出单',
							field:'id'
						})
						.then(res => {
						let delIDs = []
				for (let i = 0; i < res.data.length; i++) {
					let sr =  res.data[i]
					delIDs.push(sr.id)
					console.log(delIDs)
				}
				 Aud({
								//id: tempIDs.join(',')
						reqType:'delete',
						content:delIDs,
						tablename:'出单'
							})
							.then(res => {
								this.$message.success('删除成功')
							})
							.catch(err => {
								
							})  
													 							
						})
						.catch(err => {
							// 异常情况							
						})
				 })            
			 },

